class Solution:
    def findMinArrowShots(self, points: list[list[int]]) -> int:
        points = sorted(points, key=lambda p: (p[1], p[0]))
        arrows = 0
        last_arrow = None
        for start, end in points:
            if last_arrow is None or start > last_arrow:
                arrows += 1
                last_arrow = end
        return arrows

